// Define the AnimatedBackground component
const AnimatedBackground = () => (
  <div className="fixed inset-0 -z-10">
    {/* Gradient Orbs */}
    <div className="absolute top-0 -left-4 w-72 h-72 bg-purple-300 rounded-full 
      mix-blend-multiply filter blur-xl opacity-70 animate-blob animation-delay-2000" />
    <div className="absolute top-0 -right-4 w-72 h-72 bg-yellow-300 rounded-full 
      mix-blend-multiply filter blur-xl opacity-70 animate-blob animation-delay-4000" />
    <div className="absolute -bottom-8 left-20 w-72 h-72 bg-pink-300 rounded-full 
      mix-blend-multiply filter blur-xl opacity-70 animate-blob" />

    {/* Animated Stars */}
    <div className="stars-container">
      {[...Array(50)].map((_, i) => (
        <div
          key={i}
          className="star"
          style={{
            left: `${Math.random() * 100}%`,
            top: `${Math.random() * 100}%`,
            animationDelay: `${Math.random() * 3}s`,
            animationDuration: `${2 + Math.random() * 3}s`
          }}
        />
      ))}
    </div>
  </div>
);

// Add custom styles to index.css
const CustomStyles = () => (
  <style>{`
    @import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;500;600;700&family=Cormorant+Garamond:wght@300;400;500;600;700&display=swap');

    .animate-blob {
      animation: blob 7s infinite;
    }

    .animation-delay-2000 {
      animation-delay: 2s;
    }

    .animation-delay-4000 {
      animation-delay: 4s;
    }

    @keyframes blob {
      0% {
        transform: translate(0px, 0px) scale(1);
      }
      33% {
        transform: translate(30px, -50px) scale(1.1);
      }
      66% {
        transform: translate(-20px, 20px) scale(0.9);
      }
      100% {
        transform: translate(0px, 0px) scale(1);
      }
    }

    .star {
      position: absolute;
      width: 2px;
      height: 2px;
      background: white;
      border-radius: 50%;
      animation: twinkle linear infinite;
      opacity: 0;
    }

    @keyframes twinkle {
      0% { opacity: 0; transform: scale(1); }
      50% { opacity: 0.5; transform: scale(1.5); }
      100% { opacity: 0; transform: scale(1); }
    }

    body {
      font-family: 'Cormorant Garamond', serif;
    }

    h1, h2, h3, h4, h5, h6 {
      font-family: 'Cinzel', serif;
    }
  `}</style>
);

interface User {
  name: string;
  dateOfBirth: string;
  timeOfBirth: string;
  gender: string;
  state: string;
  city: string;
}

const App = () => {
  const [user, setUser] = useState<User | null>(null);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isChatOpen, setIsChatOpen] = useState(false);

  const handleUserRegistration = (userData: User) => {
    setUser(userData);
  };

  const toggleChat = () => {
    setIsChatOpen(!isChatOpen);
  };

  return (
    <Router>
      <CustomStyles />
      <div className={`min-h-screen ${isDarkMode ? 'dark' : ''}`}>
        <AnimatedBackground />
        <div className="flex flex-col min-h-screen backdrop-blur-sm">
          <Navbar />

          {/* Chat Toggle Button */}
          <button
            onClick={toggleChat}
            className="fixed bottom-6 right-6 z-50 bg-purple-600/80 hover:bg-purple-700/80 
            text-white rounded-full p-4 shadow-lg transition-all duration-300 
            backdrop-blur-sm transform hover:scale-110"
            aria-label="Toggle chat"
          >
            {isChatOpen ? (
              <X className="w-6 h-6" />
            ) : (
              <MessageCircle className="w-6 h-6" />
            )}
          </button>

          {/* Chat Interface */}
          <div
            className={`fixed bottom-24 right-6 z-40 transition-transform duration-300 
            transform ${isChatOpen ? 'translate-x-0' : 'translate-x-[400px]'}`}
          >
            <div className="w-[350px] h-[500px] bg-white/90 dark:bg-gray-800/90 
              rounded-lg shadow-xl backdrop-blur-md">
              {isChatOpen && <ChatInterface />}
            </div>
          </div>

          {/* Main Content */}
          <main className="flex-grow container mx-auto px-4 py-8">
            <Routes>
              <Route path="/" element={<HomePage />} />
              <Route 
                path="/dashboard" 
                element={
                  user ? (
                    <Dashboard user={user} />
                  ) : (
                    <Navigate to="/birth-details" replace />
                  )
                } 
              />
              <Route 
                path="/birth-details" 
                element={
                  user ? (
                    <Navigate to="/dashboard" replace />
                  ) : (
                    <BirthDetailsPage onSubmit={handleUserRegistration} />
                  )
                } 
              />
              <Route path="/services" element={<ServicesPage />} />
              <Route path="/about" element={<AboutPage />} />
              <Route path="/contact" element={<ContactPage />} />
              <Route path="/testimonials" element={<TestimonialsPage />} />
            </Routes>
          </main>

          {/* Footer */}
          <footer className="bg-white/80 dark:bg-gray-800/80 shadow-lg mt-auto backdrop-blur-sm">
            <div className="container mx-auto px-4 py-6">
              <div className="flex flex-col md:flex-row justify-between items-center">
                <div className="text-gray-600 dark:text-gray-300 text-sm">
                  © 2025 SoulBuddy. All rights reserved.
                </div>
                <div className="flex space-x-4 mt-4 md:mt-0">
                  <a 
                    href="#" 
                    className="text-gray-600 dark:text-gray-300 hover:text-purple-600 
                    dark:hover:text-purple-400 transition-colors duration-200"
                  >
                    Privacy Policy
                  </a>
                  <a 
                    href="#" 
                    className="text-gray-600 dark:text-gray-300 hover:text-purple-600 
                    dark:hover:text-purple-400 transition-colors duration-200"
                  >
                    Terms of Service
                  </a>
                  <a 
                    href="#" 
                    className="text-gray-600 dark:text-gray-300 hover:text-purple-600 
                    dark:hover:text-purple-400 transition-colors duration-200"
                  >
                    Contact Support
                  </a>
                </div>
              </div>
            </div>
          </footer>
        </div>
      </div>
    </Router>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ChatMessage } from '../types';

const ChatInterface: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const messagesEndRef = useRef<null | HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim()) return;

    const userMessage: ChatMessage = {
      id: Date.now().toString(),
      text: input,
      sender: 'user',
      timestamp: new Date(),
    };

    setMessages((prev) => [...prev, userMessage]);
    setInput('');

    // Simulate bot response - In production, this would call your AI backend
    setTimeout(() => {
      const botMessage: ChatMessage = {
        id: (Date.now() + 1).toString(),
        text: "I'm analyzing your astrological chart. Based on your planetary positions, I can see that...",
        sender: 'bot',
        timestamp: new Date(),
      };
      setMessages((prev) => [...prev, botMessage]);
    }, 1000);
  };

  return (
    <div className="flex flex-col h-[600px] bg-white rounded-lg shadow-lg">
      <div className="p-4 border-b border-gray-200">
        <h2 className="text-xl font-semibold text-gray-800">Your Spiritual Guide</h2>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        <AnimatePresence>
          {messages.map((message) => (
            <motion.div
              key={message.id}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0 }}
              className={`flex ${message.sender === 'user' ? 'justify-end' : 'justify-start'}`}
            >
              <div
                className={`max-w-[80%] rounded-lg p-4 ${
                  message.sender === 'user'
                    ? 'bg-primary-600 text-white'
                    : 'bg-gray-100 text-gray-800'
                }`}
              >
                <p className="text-sm">{message.text}</p>
                <span className="text-xs opacity-75 mt-1 block">
                  {message.timestamp.toLocaleTimeString()}
                </span>
              </div>
            </motion.div>
          ))}
        </AnimatePresence>
        <div ref={messagesEndRef} />
      </div>

      <form onSubmit={handleSend} className="p-4 border-t border-gray-200">
        <div className="flex space-x-4">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Ask about your astrological insights..."
            className="flex-1 rounded-lg border border-gray-300 px-4 py-2 focus:outline-none focus:border-primary-500"
          />
          <button
            type="submit"
            className="bg-primary-600 text-white px-6 py-2 rounded-lg hover:bg-primary-700 transition-colors"
          >
            Send
          </button>
        </div>
      </form>
    </div>
  );
};

export default ChatInterface;

