            <h3 className="text-xl font-semibold mb-4">Recommended Gemstones</h3>
            <div className="space-y-4">
              {horoscopeData.recommendations.gemstones.map((gemstone) => (
                <div key={gemstone.name} className="flex items-center space-x-4">
                  <div className="w-3 h-3 rounded-full bg-primary-500"></div>
                  <div>
                    <p className="font-medium">{gemstone.name}</p>
                    <p className="text-sm text-gray-600">{gemstone.benefits}</p>
