          {/* Logo and Brand */}
          <div className="flex-shrink-0 flex items-center">
            <Link to="/" className="flex items-center">
              <span className="text-2xl font-bold text-purple-600 dark:text-purple-400">
                SoulBuddy
              </span>
            </Link>
          </div>

          {/* Desktop Navigation */}
